function Gear({at=[0,0,0],radius=.8,teeth=20,color='#b7a06c'}:{at?:V3;radius?:number;teeth?:number;color?:string}){const geom=useMemo(()=>{const shape=new THREE.Shape();for(let i=0;i<teeth*4;i++){const a=i*Math.PI*2/(teeth*4),r=i%4===0||i%4===3?radius*.85:radius;const x=Math.cos(a)*r,y=Math.sin(a)*r;i===0?shape.moveTo(x,y):shape.lineTo(x,y)}shape.closePath();const hole=new THREE.Path();hole.absarc(0,0,radius*.2,0,Math.PI*2,true);shape.holes.push(hole);const geometry=new THREE.ExtrudeGeometry(shape,{depth:.22,bevelEnabled:true,bevelSegments:2,steps:1,bevelSize:.018,bevelThickness:.018,curveSegments:24});geometry.center();return geometry},[radius,teeth]);return <mesh geometry={geom} position={at} rotation={[-Math.PI/2,0,0]} castShadow receiveShadow><Surface color={color} metal={.83} rough={.3}/></mesh>}
